function chooseDestination(p,fly=true){clearJourneyMap();destination={...p};$('#destination-input').value=name(p);planVersion++;searchVersion++;setLabel('#destination-label',name(p.name)||'Pinned destination',!!p.name);$('#destination-note').textContent=`Destination set · ${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}. Drag the red pin to adjust.`;$('#places').innerHTML='';$('#journeys').innerHTML='';ensureDestinationMap();putDestinationPin();if(fly)destMap?.flyTo({center:coords(destination),zoom:17})}
