function geocoderPlace(f){let p=f.properties,c=f.geometry.coordinates,street=[p.street,p.housenumber].filter(Boolean).join(' '),primary=p.name||street||p.city||'Map location',secondary=[p.name?street:'',p.city||p.district||p.county].filter(Boolean).join(' · ');return {lon:c[0],lat:c[1],name:primary,detail:secondary,house:p.housenumber||'',source:'Address',type:placeType(p),street:p.street||p.name||''}}
async function searchEndpoint(kind){const start=kind==='origin',container=$(start?'#origin-places':'#places');let q=$(start?'#origin-input':'#destination-input').value.trim();if(q.length<2)return;let version=start?++originSearchVersion:++searchVersion;container.innerHTML='<p class="notice">Searching places and addresses…</p>';let clean=q.replace(/(\d+)\s*\/\s*\d+/, '$1'),house=clean.match(/\b(\d+[a-z]?)\b/i)?.[1],street=clean.replace(/\b\d+[a-z]?\b/gi,'').trim();let local=db?db.stops.filter(s=>norm(name(s)).includes(norm(street||q))).slice(0,10).map(s=>({...s,name:name(s),detail:'Bus stop '+(s.stop_code||s.id),source:'Stop',type:'Bus stop'})):[],places=[],failed=false;try{let queries=[clean];if(house&&street.length>3)queries.push(street);for(let term of queries){let u='https://photon.komoot.io/api/?q='+encodeURIComponent(term)+'&lat=41.997&lon=21.431&limit=40&bbox=21.20,41.80,21.65,42.20';let r=await fetch(u,{signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();let result=await r.json();places.push(...result.features.map(geocoderPlace).filter(p=>distance(p,{lat:41.997,lon:21.431})<40000))}}catch{failed=true}if(version!==(start?originSearchVersion:searchVersion))return;let matching=p=>!!house&&norm(p.house)===norm(house)&&norm(p.street||p.name).includes(norm(street.replace(/\bstreet\b/gi,''))),seen=new Set();const choices=rankPlaces([...places,...local],q).sort((a,b)=>(matching(a)?0:1)-(matching(b)?0:1)||a.score-b.score);if(start)originChoices=choices;else placeChoices=choices;let exact=house&&choices.some(matching);let note=failed?'Address search is unavailable. You can still pin the exact location below.':house&&!exact?`House number ${esc(house)} is not in the available address results. These are nearby/street matches; use the destination pin for your exact house.`:house?'A “house number match” refers to the mapped building; apartment/unit numbers are not usually listed.':'Select a result or place the destination pin below.';if(start)note=failed?'Address search is unavailable. Try a stop name or use your location.':'Select your starting point.';container.innerHTML=`<p class="notice">${note}</p>`+choices.map((p,i)=>`<button class="place" ${start?'data-origin-place':'data-place'}="${i}"><strong>${esc(name(p.name))}${p.exact?'<span class="place-match">Exact match</span>':''}</strong><small>${esc(p.type||p.source)} · ${esc(name(p.detail))}${matching(p)?' · House number match':''}</small></button>`).join('')+(choices.length?'':`<div class="empty">${start?'No matching places found. Try another search.':'No matching places found. Tap the destination map.'}</div>`)};

