function showJourney(index){
 const result=journeyResults[index];if(!result?.legs.length)return;
 if(ride)endRide();
 activeJourney?.controller?.abort();
 const snapshot={...result,legs:result.legs.map(l=>({...l,from:{...l.from},to:{...l.to}}))};
 const steps=snapshot.legs.map((l,i)=>({l,i})).filter(({l})=>l.type!=='walk'||l.meters>=10||snapshot.legs.length===1).map(x=>x.i);
 activeJourney={result:snapshot,steps,step:steps[0]??0,follow:false,context:journeyContext?{...journeyContext,options:{...journeyContext.options}}:null,geometry:journeyGeometry(db,snapshot),controller:new AbortController()};
 passengerReports.watch(null);$('#passenger-prompt').hidden=true;$('#passenger-updates').hidden=true;
 stopId=null;targetStopId=null;selectedVehicle=null;chosenLines.clear();correcting=false;$('#location-edit').hidden=true;if(origin)placeOrigin(origin);
 document.body.classList.add('following-journey');
 for(const id of ['change-stop','show-routes','show-buses','correct-location'])$('#'+id).hidden=true;
 updateFollowControl();activate('home');setSheet(false);updateStopLayer();updateVehicles();fitJourney();watchLocation();loadWalking(activeJourney);
}
function journeyStepTitle(leg){return leg.type==='bus'?'Bus '+line(leg.route)+' · '+name(leg.headsign):leg.type==='transfer'?'Change buses':'Walk to '+(name(leg.to)||'your destination');}
function currentJourneyStatus(now=Date.now()){
 const context=activeJourney.context,live=context?.options.mode&&context.options.mode!=='now'?null:rt;
 return journeyStatus(db,live,activeJourney.result,now,context?.options.mode==='arrive'?context.time:null);
}
function journeyDeadline(){return activeJourney?.context?.options.mode==='arrive'?activeJourney.context.time:null;}
function journeyFollowPanel(){
 const selected=activeJourney,leg=selected.result.legs[selected.step],at=selected.steps.indexOf(selected.step),last=at===selected.steps.length-1;
 const next=last?'Finish journey':leg.type==='bus'?'I’ve got off':leg.type==='transfer'?'At the next stop':'I’m at the stop';
 return `<div class="journey-follow-panel"><div class="journey-follow-heading"><span class="label">YOUR JOURNEY · STEP ${at+1} OF ${selected.steps.length}</span><button class="textbtn" data-end-journey>End</button></div><h2>${esc(journeyStepTitle(leg))}</h2><div id="chosen-journey-info" class="journey-follow-info" aria-live="polite">${journeyStepInfo()}</div><div class="journey-step-actions"><button class="secondary" data-journey-previous ${at===0?'disabled':''} aria-label="Previous journey step">←</button><button class="primary" data-journey-next>${next}</button><button class="secondary" data-journey-overview aria-label="Show the whole journey">Overview</button></div><p class="journey-location-status" id="journey-location-status">${esc(journeyLocationStatus())}</p><div class="journey-follow-summary"><strong id="chosen-journey-arrival"></strong><span>Steps change when you tap Next or select a step below.</span></div><ol class="journey-step-list">${selected.steps.map((index,i)=>{const l=selected.result.legs[index];return `<li><button data-journey-step="${index}" ${index===selected.step?'aria-current="step"':''}><span class="step-number">${i+1}</span><span><strong>${esc(journeyStepTitle(l))}</strong><small>${l.type==='bus'?esc(name(l.from))+' → '+esc(name(l.to)):l.type==='transfer'?esc(name(l.from))+' → '+esc(name(l.to)):(l.walkingPath?'':'~')+Math.round(walkingDistance(l))+' m · '+(l.walkingPath?'street walking directions':'approximate walk')}</small></span></button></li>`;}).join('')}</ol><div class="journey-extra-actions"><button class="secondary" data-replan>${leg.type==='bus'?'Missed this bus?':'Find another journey'}</button><button class="textbtn" data-share-journey>Share journey</button></div><div id="chosen-journey-alerts">${serviceNotices(currentJourneyStatus().legs)}</div><p class="notice">Connections are estimates. Keep Tuka open for location updates.</p></div>`;
}
function journeyStepInfo(){
 if(!activeJourney)return '';
 const status=currentJourneyStatus(),leg=status.legs[activeJourney.step];
 const time=t=>journeyClock(t,Date.now());let detail='';
 if(leg.type==='bus'){
  detail=`<p>Board at <strong data-no-translate>${esc(name(leg.from))}</strong><br>Get off at <strong data-no-translate>${esc(name(leg.to))}</strong></p><div class="journey-live-times"><span>${time(leg.start)}<small>${leg.live?'Live departure estimate':'Scheduled departure'}</small></span><span>~${time(leg.end)}<small>${leg.arrivalLive?'Live arrival estimate':'Timetable arrival'}</small></span></div>`;
  detail+=accessibilityHTML([leg]);const vehicles=journeyVehicles(rt,{legs:[leg]});detail+=`<small>${leg.stops} stops · ${vehicles.length?'Bus GPS shown on the map':'No fresh GPS for this bus'}</small>`;
  if(leg.cancelled||leg.skipped)detail+='<p class="connection-banner">'+(leg.cancelled?'This bus is reported cancelled.':'This boarding or exit stop is reported skipped.')+' Check another journey before continuing.</p>';
  else if(leg.start<Date.now()-60000)detail+='<p class="journey-time-note">Departure time has passed. If you haven’t boarded, check another journey.</p>';
 }else{
  detail=`<p>${leg.type==='transfer'?'Continue to':'Head to'} <strong ${name(leg.to)?'data-no-translate':''}>${esc(name(leg.to)||'your destination')}</strong></p><small>${leg.walkingPath?'':'~'}${Math.round(walkingDistance(leg))} m · ${minutes(leg.walkingMs||leg.end-leg.start)} min walking${leg.type==='transfer'?' + '+minutes(leg.bufferMs||0)+' min transfer buffer':''}</small>`;
  const next=status.legs.slice(activeJourney.step+1).find(l=>l.type==='bus');if(next)detail+=`<p class="journey-next-bus">Then bus <strong>${esc(line(next.route))}</strong> · ${time(next.start)} · ${next.live?'live estimate':'timetable'}</p>`;
 }
 if(leg.type!=='bus')detail+=walkingDetails(leg);
 const transfer=leg.type==='transfer'?leg:status.legs[activeJourney.step+1]?.type==='transfer'?status.legs[activeJourney.step+1]:null;
 if(transfer?.connection){const margin=transfer.connection.marginMs;detail+=`<p class="${margin<120000?'connection-banner':'journey-time-note'}">${margin<0?'Connection at risk · '+minutes(-margin)+' min short':margin<120000?'Tight connection · '+minutes(margin)+' min spare':'Connection margin · '+minutes(margin)+' min spare'} after walking and your transfer buffer.</p>`;}
 if(activeJourney.step===activeJourney.steps[0]&&status.legs[0]?.type==='walk'&&status.legs[1]?.type==='bus'&&status.legs[0].start+status.legs[0].walkingMs>status.legs[1].start)detail+='<p class="connection-banner">The street walk may take longer than the time before your bus. Find another journey.</p>';
 const deadline=journeyDeadline();
 if(Number.isFinite(deadline)){detail+=`<p class="${status.deadlineMissed?'connection-banner':'journey-time-note'}">${status.deadlineMissed?'<strong>Arrival deadline missed</strong><br>':''}Arrive by ${time(deadline)} · ${minutes(status.deadlineMissed?status.latenessMs:Math.max(0,deadline-status.arrival))} min ${status.deadlineMissed?'late':'spare'}${status.deadlineMissed?`<br>Estimated arrival ~${time(status.arrival)}. Find another journey.`:''}</p>`;}
 if(activeJourney.geometry.paths.features[activeJourney.step]?.properties.approximate&&leg.type==='bus')detail+='<small>Approximate stop outline · street geometry unavailable.</small>';
 return detail;
}
function journeyLocationStatus(){return Date.now()-lastLocation<25000?(activeJourney?.follow?'Following your location':'Location visible · tap ◎ to follow'):'Location unavailable or paused · you can follow the steps manually';}
function stableHTML(element,html){if(!element||element.tukaMarkup===html)return;const opened=[...element.querySelectorAll('details')].map(d=>d.open);element.innerHTML=html;element.tukaMarkup=html;[...element.querySelectorAll('details')].forEach((d,i)=>d.open=opened[i]||false);}
