async function loadWalking(selected){
 const {signal}=selected.controller;
 for(const leg of selected.result.legs){
  if(signal.aborted)return;if(leg.type==='bus'||leg.meters<10)continue;
  leg.walkStatus='loading';if(activeJourney===selected)updateJourneyInfo();
  try{
   const route=await walkingPath(leg.from,leg.to,signal);if(signal.aborted)return;
   leg.walkingPath=route.coordinates;leg.walkingSteps=route.steps;leg.walkingMeters=route.distance;leg.walkingMs=Math.ceil(route.distance/((selected.context?.options.walkingSpeed||4.5)*1000/3600))*1000;leg.walkStatus='ready';
   selected.geometry=journeyGeometry(db,selected.result);
  }catch{if(signal.aborted)return;leg.walkStatus='failed';}
  if(activeJourney===selected){renderHome();updateHomeRoute();}
  await new Promise(resolve=>{const timer=setTimeout(done,1250);function done(){clearTimeout(timer);signal.removeEventListener('abort',done);resolve();}signal.addEventListener('abort',done,{once:true});});
 }
}
